+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const successMessage = document.getElementById('successMessage');
+
+const emailErrorId = 'email-error';
+
+function validateEmail(email) {
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    return emailRegex.test(email);
+}
+
+function validatePhoneFormat(phone) {
+    if (!phone) return true;
+    const phoneRegex = /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4})$/;
+    return phoneRegex.test(phone.trim());
+}
+
+function showFieldError(inputElement, errorMessage) {
+    const errorId = `${inputElement.id}-error`;
+
+    let errorElement = document.getElementById(errorId);
+    if (!errorElement) {
+        errorElement = document.createElement('p');
+        errorElement.id = errorId;
+        errorElement.className = 'error-message';
+        inputElement.parentNode.appendChild(errorElement);
+    }
+
+    errorElement.textContent = `Error: ${errorMessage}`;
+
+    const describedBy = inputElement.getAttribute('aria-describedby') || '';
+    const ids = describedBy.split(' ').filter(id => id && id !== errorId);
+    ids.push(errorId);
+    inputElement.setAttribute('aria-describedby', ids.join(' '));
+    inputElement.setAttribute('aria-invalid', 'true');
+}
+
+function clearFieldError(inputElement) {
+    const errorId = `${inputElement.id}-error`;
+    const errorElement = document.getElementById(errorId);
+    if (errorElement) {
+        errorElement.remove();
+    }
+
+    const describedBy = inputElement.getAttribute('aria-describedby') || '';
+    const ids = describedBy.split(' ').filter(id => id && id !== errorId);
+    if (ids.length > 0) {
+        inputElement.setAttribute('aria-describedby', ids.join(' '));
+    } else {
+        inputElement.removeAttribute('aria-describedby');
+    }
+    inputElement.setAttribute('aria-invalid', 'false');
+}
+
+function validateForm() {
+    let isValid = true;
+    const firstInvalidField = null;
+
+    if (!fullNameInput.value.trim()) {
+        showFieldError(fullNameInput, 'Please enter your full name.');
+        isValid = false;
+    } else {
+        clearFieldError(fullNameInput);
+    }
+
+    if (!emailInput.value.trim()) {
+        showFieldError(emailInput, 'Please enter your email address.');
+        isValid = false;
+    } else if (!validateEmail(emailInput.value)) {
+        showFieldError(emailInput, 'Please enter a valid email address.');
+        isValid = false;
+    } else {
+        clearFieldError(emailInput);
+    }
+
+    if (phoneInput.value.trim() && !validatePhoneFormat(phoneInput.value)) {
+        showFieldError(phoneInput, 'Please use format (123) 456-7890 or 123-456-7890.');
+        isValid = false;
+    } else {
+        clearFieldError(phoneInput);
+    }
+
+    return isValid;
+}
+
+function focusFirstInvalidField() {
+    if (fullNameInput.getAttribute('aria-invalid') === 'true') {
+        fullNameInput.focus();
+    } else if (emailInput.getAttribute('aria-invalid') === 'true') {
+        emailInput.focus();
+    } else if (phoneInput.getAttribute('aria-invalid') === 'true') {
+        phoneInput.focus();
+    }
+}
+
+function hideSuccessMessage() {
+    successMessage.classList.add('hidden');
+    successMessage.setAttribute('aria-hidden', 'true');
+}
+
+function showSuccessMessage() {
+    successMessage.classList.remove('hidden');
+    successMessage.setAttribute('aria-hidden', 'false');
+}
+
+function resetForm() {
+    form.reset();
+    hideSuccessMessage();
+    clearFieldError(fullNameInput);
+    clearFieldError(emailInput);
+    clearFieldError(phoneInput);
+}
+
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    if (validateForm()) {
+        console.log('Form submitted:', {
+            fullName: fullNameInput.value,
+            email: emailInput.value,
+            phone: phoneInput.value || '(not provided)',
+        });
+
+        showSuccessMessage();
+        form.style.display = 'none';
+
+        setTimeout(() => {
+            resetForm();
+            form.style.display = 'flex';
+            fullNameInput.focus();
+        }, 3000);
+    } else {
+        focusFirstInvalidField();
+    }
+});
+
+phoneInput.addEventListener('input', () => {
+    if (phoneInput.value && !validatePhoneFormat(phoneInput.value)) {
+        phoneInput.setAttribute('aria-invalid', 'true');
+    } else {
+        phoneInput.setAttribute('aria-invalid', 'false');
+    }
+});
+
")

