const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf-8');
  await page.setContent(html, { waitUntil: 'load' });

  // Load axe-core from node_modules
  const axeSource = fs.readFileSync(
    path.join(__dirname, 'node_modules', 'axe-core', 'axe.min.js'),
    'utf-8'
  );
  await page.addInitScript(axeSource);

  const results = await page.evaluate(() => window.axe.run());

  // Filter violations
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpWarnings = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcagViolations.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      nodes: v.nodes.map(n => ({
        html: n.html,
        target: n.target
      }))
    })),
    bp: bpWarnings.map(v => ({
      id: v.id,
      description: v.description,
      nodes: v.nodes.map(n => ({
        html: n.html,
        target: n.target
      }))
    })),
    passes: results.passes.length,
    inapplicable: results.inapplicable.length
  }, null, 2));

  await browser.close();
  process.exit(wcagViolations.length > 0 ? 1 : 0);
})();

